    #[test]
    fn supplied_peer_key_or_wristband_cannot_select_full_access_route() {
        // The production route_client path uses this same decision function.
        // No plaintext key storage is constructed to test legacy denial.
        let peer_key = hex::encode([7_u8; 32]);
        let wristband = Uuid::new_v4().to_string();

        for token in [None, Some(wristband)] {
            let decision = McpGatewayManager::blocked_decision(&McpClientInfo {
                name: "unverified-caller".into(),
                version: None,
                user_agent: None,
                ip_address: None,
                auth_token=***                peer_pubkey: Some(peer_key.clone()),
            });
            assert!(matches!(decision.access_level, AccessLevel::Blocked));
            assert!(!decision.has_full_access);
            assert!(decision.endpoint.is_empty());
            assert!(decision.allowed_tools.is_empty());
            assert!(decision.capabilities.is_empty());
        }
    }
}

